                    "localId": "29e4c22f630c"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the component is rendered with valid props, when it mounts, then it displays the lookbook image slot on the left and the configured number of product tile slots on the right, matching the Figma spec for the given `grid` and `qty` combination."
                        }
                      ],
                      "attrs": {
                        "localId": "0cde1c0fef08"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "3bb106b9edcf"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `showTitleAndLink=true`, when the component renders, then the section header displays both the title and link."
                        }
                      ],
                      "attrs": {
                        "localId": "bf28a81df206"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "7b076387171b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `showTitleAndLink=false`, when the component renders, then the section header is not displayed."
                        }
                      ],
                      "attrs": {
                        "localId": "eb0dc6e8bde3"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "29c1925f0286"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given "
                        },
                        {
                          "type": "text",
                          "text": "cardType=Product",
                          "marks": [
                            {
                              "type": "code"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": ", ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "when the component renders, then the lookbook slot displays a standard product shot image."
                        }
                      ],
                      "attrs": {
                        "localId": "ce1f50296099"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "9bedc252cba4"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given "
                        },
                        {
                          "type": "text",
                          "text": "cardType=Editorial",
                          "marks": [
                            {
                              "type": "code"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": ",",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": " when the component renders, then the lookbook slot displays an editorial/campaign image."
                        }
                      ],
                      "attrs": {
                        "localId": "133171b69a4f"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "2b482fa15cfa"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `grid=3` at desktop with any qty value, when the component renders, then the lookbook image occupies approximately two-thirds of the component width and product tiles stack in the remaining column, matching the Figma grid-3 spec."
                        }
                      ],
                      "attrs": {
                        "localId": "98c1916ffc96"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "90d70530167e"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `grid=4` at desktop with any qty value, when the component renders, then the lookbook image occupies approximately three-quarters of the component width and product tiles stack in the narrower remaining column, matching the Figma grid-4 spec."
                        }
                      ],
                      "attrs": {
                        "localId": "d2638f4ad8f1"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ac7c5fe0c584"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `qty=5` at desktop, when the component renders, then the lookbook image is displayed and 4 product tiles render in a 2x2 grid to the right, matching the Figma qty-5 spec."
                        }
                      ],
                      "attrs": {
                        "localId": "bb12d7cdac64"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "b8878e78f506"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `size=Desktop`, when the component mounts, then it renders in the grid layout matching the Figma desktop spec for the active `grid` and `qty` values."
                        }
                      ],
                      "attrs": {
                        "localId": "7c32dfeeae09"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "132989018c9e"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `size=Tablet`, when the component mounts, then the lookbook image renders full-width at the top and product tiles render below using the Mobile card size, matching the Figma tablet spec."
                        }
                      ],
                      "attrs": {
                        "localId": "fda0d96b325b"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "02a6c7e9636c"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `size=Mobile`, when the component mounts, then the layout matches the Figma mobile spec using the Mobile card size."
                        }
                      ],
                      "attrs": {
                        "localId": "56af1c74e5db"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "85fcbbb5c371"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given `size=Desktop`, when the component renders, then `imageGroup.showCarousel` controls carousel visibility and `imageGroup.showSlideIndicator` has no effect."
                        }
                      ],
                      "attrs": {
                        "localId": "65447274c536"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "70cab62ebdcc"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the component is rendered with an empty or missing product array, when it mounts, then no product cards are rendered and no error is thrown."
                        }
                      ],
                      "attrs": {
                        "localId": "fe143830f5e8"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "5695de6e212c"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the component is interactive, when a keyboard user navigates through it, then all interactive elements are reachable and activatable via keyboard alone."
                        }
                      ],
                      "attrs": {
                        "localId": "64314ccbe149"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "266031b4976f"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given WCAG 2.1 AA criteria, when the component is tested, then it passes with no violations."
                        }
                      ],
                      "attrs": {
                        "localId": "657569261688"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "rule",
              "attrs": {
                "localId": "4ea743c5b577"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 16,
                "localId": "b29727d89430"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "30a3f9264c70"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Tablet behaviour – ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "qty=5",
                          "marks": [
                            {
                              "type": "code"
                            }
                          ]
                        }
                      ],
                      "attrs": {
                        "localId": "5a727c1e89aa"
                      }
                    },
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "The "
                        },
                        {
                          "type": "text",
                          "text": "qty=5",
                          "marks": [
                            {
                              "type": "code"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": " configuration renders 1 large product card and 4 small product cards on desktop. On tablet, only 3 small product cards are rendered — the 4th small card is hidden. This prevents an awkward orphaned card from appearing on its own row, as tablet uses a 3-column grid system."
                        }
                      ],
                      "attrs": {
                        "localId": "bcdd8ad4b9e5"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
      }
