      },
      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "paragraph",
              "attrs": {
                "localId": "db49f74f5d04"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "d3f831d785c0"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "98031093aec8"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper visits any page on the site, when the page loads, then a breadcrumb is displayed reflecting the current page hierarchy (e.g. HOME / COLLECTIONS / RTW), generated programmatically from the page context and not hardcoded."
                        }
                      ],
                      "attrs": {
                        "localId": "fad4795d6c89"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "9ca33ada6ae3"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper visits a category or sub-category page that has a published Contentful entry for that category ID, when the page loads, then the title and intro text render below the breadcrumb above the footer."
                        }
                      ],
                      "attrs": {
                        "localId": "699c09c42e5c"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "1e2c9e8d2c0c"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a category or sub-category page has no published Contentful entry configured for that category ID, when the page loads, then the breadcrumb renders as normal but no SEO text block or empty container renders beneath it."
                        }
                      ],
                      "attrs": {
                        "localId": "6070ea6ae069"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "74b90cd47c49"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a Contentful entry exists for a category but the expanded SEO body field is empty, when the page loads, then the READ MORE link does not render."
                        }
                      ],
                      "attrs": {
                        "localId": "3b972d24d02c"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "8ff2affe4254"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the SEO text block is in its collapsed state and a READ MORE link is present, when a shopper clicks READ MORE, then the component expands inline to reveal the full SEO body content and READ MORE is replaced by READ LESS."
                        }
                      ],
                      "attrs": {
                        "localId": "22f813abf2a1"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "d07769f0cf67"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the SEO text component is in its expanded state, when a shopper clicks READ LESS, then the component collapses back to the default state showing only the title, intro text, and READ MORE link."
                        }
                      ],
                      "attrs": {
                        "localId": "947f1727ce6b"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "6b67d7bfdd52"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given Contentful entries are configured per category ID, when a shopper navigates between different category and sub-category pages, then each page renders its own configured SEO content — or no SEO block if no entry exists for that category."
                        }
                      ],
                      "attrs": {
                        "localId": "1cd1ae876956"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "a5530cf18ac3"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given Contentful entries are configured for different locales, when a shopper views a category page on a given locale, then the SEO text reflects the content configured for that locale."
                        }
                      ],
                      "attrs": {
                        "localId": "ed1d27e395e2"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "447331e923f8"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper navigates to any page, when the breadcrumb renders, then it is marked up using a "
                        },
                        {
                          "type": "text",
                          "text": "<nav>",
                          "marks": [
                            {
                              "type": "code"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": " element with an appropriate aria-label (e.g. \"Breadcrumb\") and structured as an ordered list so screen readers can announce the hierarchy correctly."
                        }
                      ],
                      "attrs": {
                        "localId": "1ea4aabbd03f"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "624cf01db0ef"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a keyboard-only user is navigating the breadcrumb, when they tab through it, then each breadcrumb link is reachable and activatable via keyboard and focus is visible throughout."
                        }
                      ],
                      "attrs": {
                        "localId": "da4930c506f9"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "a45770ea7b80"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a keyboard-only user is on a category page with a READ MORE link, when they tab to it and press Enter or Space, then the SEO content expands and focus moves into the expanded content. When they tab to READ LESS and press Enter or Space, then the content collapses and focus returns to the READ MORE link."
                        }
                      ],
                      "attrs": {
                        "localId": "a2d08580f560"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "448d897c5d8b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a screen reader user interacts with the READ MORE link, when they activate it, then the expanded/collapsed state is correctly announced and the revealed content is accessible and readable in document order."
                        }
                      ],
                      "attrs": {
                        "localId": "2045357a611d"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "adebd047cfff"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a user has enabled reduced motion at OS level, when the SEO text expands or collapses, then any animation respects the reduced motion preference."
                        }
                      ],
                      "attrs": {
                        "localId": "5e12fdf72be9"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
      }
